<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireAdmin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');$username=trim($_POST['username']);$name=trim($_POST['full_name']);$password=$_POST['password'];$role=$_POST['role']==='admin'?'admin':'cashier';if($username&&$name&&strlen($password)>=8){try{$db->prepare('INSERT INTO users(username,password,full_name,role) VALUES(?,?,?,?)')->execute(array($username,password_hash($password,PASSWORD_DEFAULT),$name,$role));Helper::flash('تم إنشاء المستخدم.','success');}catch(PDOException $e){Helper::flash('تعذر إنشاء المستخدم. قد يكون اسم المستخدم مستخدماً.','danger');}}else Helper::flash('أدخل البيانات، ويجب ألا تقل كلمة المرور عن 8 أحرف.','danger');Helper::redirect('modules/users/index.php');}$rows=$db->query('SELECT id,username,full_name,role,active,created_at FROM users ORDER BY id')->fetchAll();$pageTitle='إدارة المستخدمين';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>إدارة المستخدمين</h1><p>إضافة حسابات المديرين والكاشير</p></div></div><div class="card mb-3"><div class="card-header">مستخدم جديد</div><div class="card-body"><form method="post" class="row g-3 align-items-end"><?= Helper::csrfField() ?><div class="col-md-3"><label class="form-label">الاسم الكامل</label><input class="form-control" name="full_name" required></div><div class="col-md-2"><label class="form-label">اسم المستخدم</label><input class="form-control" name="username" required></div><div class="col-md-3"><label class="form-label">كلمة المرور (8 أحرف على الأقل)</label><input class="form-control" name="password" type="password" minlength="8" required></div><div class="col-md-2"><label class="form-label">الصلاحية</label><select class="form-select" name="role"><option value="cashier">كاشير</option><option value="admin">مدير</option></select></div><div class="col-md-2"><button class="btn btn-coffee w-100">إنشاء</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>الاسم</th><th>اسم المستخدم</th><th>الصلاحية</th><th>الحالة</th><th>تاريخ الإنشاء</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['full_name']) ?></td><td><?= Helper::e($r['username']) ?></td><td><?= $r['role']==='admin'?'مدير':'كاشير' ?></td><td><?= $r['active']?'نشط':'موقوف' ?></td><td><?= Helper::e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
